def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    x = 5 * rng.random((dim)) - 5  # initial random candidate in [-5, 5]
    best_x = x.copy()
    best_f = func(x)

    for _ in range(budget):
        f = func(clip(x))
        if f < best_f:
            best_f = f
            best_x = clip(x)

        # adaptive sampling density around promising regions
        sigma = 2 / (1 + _ / budget) * np.std(np.clip([func(clip(x + rng.normal(size=(dim)))) for i in range(10)], -np.inf, np.inf))
        x += rng.normal(size=(dim)) * sigma

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    x_best = np.random.uniform(lb, ub, (1, dim))
    f_best = func(x_best)

    for _ in range(budget):
        x_candidate = np.clip(rng.normal(loc=x_best, scale=np.abs(ub - lb) / 2, size=(1, dim)), a_min=lb, a_max=ub)

        if func(x_candidate) < f_best:
            f_best = func(x_candidate)
            x_best = x_candidate

    return x_best

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    def generate_population(size):
        population = np.random.rand(size, dim)
        return clip(population * (ub - lb)) + lb

    def evaluate(candidate):
        return func(candidate)

    best_candidate = None
    best_fitness = float('inf')

    population_size = 100
    for _ in range(budget):
        population = generate_population(population_size)
        fitnesses = np.array([evaluate(individual) for individual in population])
        mean_fitness = np.mean(fitnesses)

        if mean_fitness < best_fitness:
            best_candidate = population[np.argmin(fitnesses)]
            best_fitness = mean_fitness

    return best_candidate
